G=load()
# demo1 mapping found earlier: {0:2,1:2,2:4,4:3,5:3}. thirds: W//3=2: col//2+1 -> 0->1st(2),1->1st(2),2->2nd(4),4->3rd(3),5->3rd(3). Consistent.
def f(g):
    bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    marker=[x for r in g for x in r if x!=bg][0]
    W=len(g[0]); b=W//3
    cmap={1:2,2:4,3:3}
    out=[]
    for r in g:
        c=r.index(marker); tb=(c//b)+1; col=cmap[tb]
        out.append([col]*W)
    return out
